function NewAI_RecoveryEvent()
    local u = GetTriggerUnit()
    local attacker = nil
    local key = GetHandleId(u)
    local pid = J88_int(GetPlayerId(GetOwningPlayer(u)) - 9)
    if (GetTriggerEventId() == EVENT_PLAYER_UNIT_DEATH) then
        FlushChildHashtable(NewAI_RecoveryData, key)
        if (udg_StuckUnits ~= nil) then
            GroupRemoveUnit(udg_StuckUnits, u)
        end
    elseif (GetTriggerEventId() == EVENT_PLAYER_UNIT_ATTACKED) then
        if ((pid >= 0) and (pid < 8)) then
            SaveInteger(NewAI_RecoveryData, key, 6, NewAI_Tick)
            SaveInteger(NewAI_RecoveryData, key, 9, Advance_Clock)
        end
        attacker = GetAttacker()
        pid = J88_int(GetPlayerId(GetOwningPlayer(attacker)) - 9)
        if ((pid >= 0) and (pid < 8)) then
            SaveInteger(NewAI_RecoveryData, GetHandleId(attacker), 6, NewAI_Tick)
            SaveInteger(NewAI_RecoveryData, GetHandleId(attacker), 9, Advance_Clock)
        end
    elseif ((pid >= 0) and (pid < 8)) then
        SaveBoolean(NewAI_RecoveryData, key, 8, (GetTriggerEventId() ~= EVENT_PLAYER_UNIT_SPELL_ENDCAST))
    end
    u = nil
    attacker = nil
end

function NewAI_RecoveryInit()
    NewAI_RecoveryData = InitHashtable()
    NewAI_CombatEvents = CreateTrigger()
    TriggerRegisterAnyUnitEventBJ(NewAI_CombatEvents, EVENT_PLAYER_UNIT_ATTACKED)
    TriggerRegisterAnyUnitEventBJ(NewAI_CombatEvents, EVENT_PLAYER_UNIT_DEATH)
    TriggerRegisterAnyUnitEventBJ(NewAI_CombatEvents, EVENT_PLAYER_UNIT_SPELL_CHANNEL)
    TriggerRegisterAnyUnitEventBJ(NewAI_CombatEvents, EVENT_PLAYER_UNIT_SPELL_CAST)
    TriggerRegisterAnyUnitEventBJ(NewAI_CombatEvents, EVENT_PLAYER_UNIT_SPELL_ENDCAST)
    TriggerAddAction(NewAI_CombatEvents, NewAI_RecoveryEvent)
end

function NewAI_Engaged(u)
    local g = CreateGroup()
    local v = nil
    local uid = GetUnitTypeId(u)
    local ground = J88_real(LoadReal(NewAI_Data, uid, 540) + 128.0)
    local air = J88_real(LoadReal(NewAI_Data, uid, 541) + 128.0)
    local r = 0.0
    local dx = 0.0
    local dy = 0.0
    local found = false
    local owner = GetOwningPlayer(u)
    local x = GetUnitX(u)
    local y = GetUnitY(u)
    GroupEnumUnitsInRange(g, x, y, RMaxBJ(ground, air), nil)
    while true do
        v = FirstOfGroup(g)
        if ((v == nil) or found) then break end
        GroupRemoveUnit(g, v)
        if ((((((((v ~= u) and (GetWidgetLife(v) > 0.4050000011920929)) and IsUnitEnemy(v, owner)) and IsUnitVisible(v, owner)) and (not IsUnitHidden(v))) and (GetUnitAbilityLevel(v, 1097625443) == 0)) and (not BlzIsUnitInvulnerable(v))) and (not IsUnitType(v, UNIT_TYPE_STRUCTURE))) then
            if IsUnitType(v, UNIT_TYPE_FLYING) then
                r = air
            else
                r = ground
            end
            dx = J88_real(x - GetUnitX(v))
            dy = J88_real(y - GetUnitY(v))
            if ((r > 128.0) and (J88_real(J88_real(dx * dx) + J88_real(dy * dy)) <= J88_real(r * r))) then
                found = true
            end
        end
    end
    DestroyGroup(g)
    g = nil
    v = nil
    owner = nil
    do return found end
end

function NewAI_RecoveryProcess()
    local u = NewAI_RecoveryActor
    local key = GetHandleId(u)
    local order = GetUnitCurrentOrder(u)
    local x = GetUnitX(u)
    local y = GetUnitY(u)
    local dx = J88_real(x - LoadReal(NewAI_RecoveryData, key, 1))
    local dy = J88_real(y - LoadReal(NewAI_RecoveryData, key, 2))
    local life = GetWidgetLife(u)
    local sx = 0.0
    local sy = 0.0
    local length = 0.0
    local sign = 1.0
    if (((((life <= 0.4050000011920929) or IsUnitPaused(u)) or IsUnitHidden(u)) or IsUnitType(u, UNIT_TYPE_STRUCTURE)) or (GetUnitAbilityLevel(u, 1097625443) > 0)) then
        u = nil
        do return end
    end
    if (((not HaveSavedInteger(NewAI_RecoveryData, key, 3)) or (J88_real(J88_real(dx * dx) + J88_real(dy * dy)) > 144.0)) or (RAbsBJ(J88_real(life - LoadReal(NewAI_RecoveryData, key, 4))) > 0.5)) then
        SaveInteger(NewAI_RecoveryData, key, 3, NewAI_Tick)
    end
    SaveReal(NewAI_RecoveryData, key, 1, x)
    SaveReal(NewAI_RecoveryData, key, 2, y)
    SaveReal(NewAI_RecoveryData, key, 4, life)
    --  Unknown active orders are native spells/abilities, never a stuck soldier.
    if ((((IsUnitInGroup(u, udg_FlyGroup) or ((GetUnitTypeId(u) == 1749108529) and Agent_Valid(u, LoadUnitHandle(Agent_Data, key, 0)))) or LoadBoolean(NewAI_RecoveryData, key, 8)) or (not Advance_OrderAllowed(order))) or (J88_int(NewAI_Tick - LoadInteger(NewAI_RecoveryData, key, 6)) <= 2)) then
        SaveInteger(NewAI_RecoveryData, key, 3, NewAI_Tick)
        u = nil
        do return end
    end
    if LoadBoolean(NewAI_RecoveryData, key, 7) then
        SaveBoolean(NewAI_RecoveryData, key, 7, false)
        if (not NewAI_Engaged(u)) then
            IssuePointOrder(u, "attack", NewAI_RecoveryGoalX, NewAI_RecoveryGoalY)
        end
        SaveInteger(NewAI_RecoveryData, key, 3, NewAI_Tick)
        u = nil
        do return end
    end
    if (((J88_int(NewAI_Tick - LoadInteger(NewAI_RecoveryData, key, 3)) < 3) or (J88_int(NewAI_Tick - LoadInteger(NewAI_RecoveryData, key, 5)) < 4)) or (NewAI_RecoveryBudget <= 0)) then
        u = nil
        do return end
    end
    NewAI_RecoveryBudget = J88_int(NewAI_RecoveryBudget - 1)
    --  An enemy merely in range is not evidence this unit has fired. Existing
    --  moving weapons have cooldowns <= 6s; allow 20s to acquire/aim before
    --  resolving congestion, while actual attack and spell events refresh 3.
    if (NewAI_Engaged(u) and (J88_int(NewAI_Tick - LoadInteger(NewAI_RecoveryData, key, 3)) < 10)) then
        u = nil
        do return end
    end
    dx = J88_real(NewAI_RecoveryGoalX - x)
    dy = J88_real(NewAI_RecoveryGoalY - y)
    length = SquareRoot(J88_real(J88_real(dx * dx) + J88_real(dy * dy)))
    if (ModuloInteger(J88_int(key + NewAI_Tick), 2) == 0) then
        sign = J88_real(-1.0)
    end
    --  A short legal sidestep can release unit congestion; no teleport,
    --  ethereal/collision cheat, or movement into another active battlefield.
    if ((length > 96.0) and (order ~= 0)) then
        sx = J88_real(x - J88_real(J88_real(J88_real(sign * dy) * 112.0) / length))
        sy = J88_real(y + J88_real(J88_real(J88_real(sign * dx) * 112.0) / length))
        if (Naval_InsideZone(NewAI_RecoveryZone, sx, sy) and (IsUnitType(u, UNIT_TYPE_FLYING) or (not IsTerrainPathable(sx, sy, PATHING_TYPE_WALKABILITY)))) then
            if IssuePointOrder(u, "move", sx, sy) then
                SaveBoolean(NewAI_RecoveryData, key, 7, true)
            end
        else
            IssuePointOrder(u, "attack", NewAI_RecoveryGoalX, NewAI_RecoveryGoalY)
        end
    else
        IssuePointOrder(u, "attack", NewAI_RecoveryGoalX, NewAI_RecoveryGoalY)
    end
    SaveInteger(NewAI_RecoveryData, key, 3, NewAI_Tick)
    SaveInteger(NewAI_RecoveryData, key, 5, NewAI_Tick)
    u = nil
end

function NewAI_RecoverySeat()
    local pid = NewAI_CurrentPid
    local site = 0
    local g = nil
    local u = nil
    if ((((not NewAI_Controlled[pid]) or NewAI_Preparing) or NewAI_Paused) or (not Naval_IsBattleActive(pid))) then
        do return end
    end
    if ((CavalryCharge_Mode == 1) and Naval_OpponentCleared(pid)) then
        do return end
    end
    NewAI_RecoveryZone = 4
    NewAI_RecoveryGoalX = 0.0
    NewAI_RecoveryGoalY = 0.0
    if ((CavalryCharge_Mode == 1) and (not Naval_OpponentCleared(pid))) then
        site = PLAYER_CURRENT_SITE[pid]
        NewAI_RecoveryZone = J88_div(site, 2)
        if (ModuloInteger(site, 2) == 0) then
            site = J88_int(site + 1)
        else
            site = J88_int(site - 1)
        end
        NewAI_RecoveryGoalX = GetRectCenterX(udg_region_Spawns[site])
        NewAI_RecoveryGoalY = GetRectCenterY(udg_region_Spawns[site])
    end
    if (not Naval_InsideZone(NewAI_RecoveryZone, NewAI_RecoveryGoalX, NewAI_RecoveryGoalY)) then
        do return end
    end
    NewAI_RecoveryBudget = 16
    g = CreateGroup()
    GroupEnumUnitsOfPlayer(g, Player(J88_int(pid + 9)), nil)
    while true do
        u = FirstOfGroup(g)
        if (u == nil) then break end
        GroupRemoveUnit(g, u)
        NewAI_RecoveryActor = u
        ExecuteFunc("NewAI_RecoveryProcess")
    end
    DestroyGroup(g)
    g = nil
    u = nil
    NewAI_RecoveryActor = nil
end

function NewAI_HellReset(pid)
    local i = 0
    NewAI_Health[pid] = 0.0
    NewAI_AirHealth[pid] = 0.0
    NewAI_FormationY[pid] = 0.0
    while true do
        if (i >= 8) then break end
        NewAI_ArmorHealth[J88_int(J88_int(pid * 8) + i)] = 0.0
        NewAI_DamageByArmor[J88_int(J88_int(pid * 8) + i)] = 0.0
        NewAI_AirArmorHealth[J88_int(J88_int(pid * 8) + i)] = 0.0
        NewAI_AADamageByArmor[J88_int(J88_int(pid * 8) + i)] = 0.0
        NewAI_RoleHealth[J88_int(J88_int(pid * 8) + i)] = 0.0
        i = J88_int(i + 1)
    end
end

function NewAI_HellAccumulate(pid, t, y)
    local i = 0
    local hp = LoadReal(NewAI_Data, t, 500)
    local role = LoadInteger(NewAI_Data, t, 4)
    NewAI_Health[pid] = J88_real(NewAI_Health[pid] + hp)
    NewAI_AirHealth[pid] = J88_real(NewAI_AirHealth[pid] + LoadReal(NewAI_Data, t, 502))
    NewAI_FormationY[pid] = J88_real(NewAI_FormationY[pid] + J88_real(hp * y))
    NewAI_RoleHealth[J88_int(J88_int(pid * 8) + role)] = J88_real(NewAI_RoleHealth[J88_int(J88_int(pid * 8) + role)] + hp)
    while true do
        if (i >= 8) then break end
        NewAI_ArmorHealth[J88_int(J88_int(pid * 8) + i)] = J88_real(NewAI_ArmorHealth[J88_int(J88_int(pid * 8) + i)] + LoadReal(NewAI_Data, t, J88_int(510 + i)))
        NewAI_DamageByArmor[J88_int(J88_int(pid * 8) + i)] = J88_real(NewAI_DamageByArmor[J88_int(J88_int(pid * 8) + i)] + LoadReal(NewAI_Data, t, J88_int(520 + i)))
        NewAI_AirArmorHealth[J88_int(J88_int(pid * 8) + i)] = J88_real(NewAI_AirArmorHealth[J88_int(J88_int(pid * 8) + i)] + LoadReal(NewAI_Data, t, J88_int(560 + i)))
        NewAI_AADamageByArmor[J88_int(J88_int(pid * 8) + i)] = J88_real(NewAI_AADamageByArmor[J88_int(J88_int(pid * 8) + i)] + LoadReal(NewAI_Data, t, J88_int(550 + i)))
        i = J88_int(i + 1)
    end
end

function NewAI_Random(pid, bound)
    NewAI_Rng[pid] = ModuloInteger(J88_int(J88_int(NewAI_Rng[pid] * 25173) + 13849), 65536)
    do return ModuloInteger(NewAI_Rng[pid], bound) end
end

function NewAI_HimmlerConverts(t)
    do return ((((((t == 1747989556) or (t == 1747989334)) or (t == 1747989337)) or (t == 1747989336)) or (t == 1747989552)) or (t == 1747989335)) end
end

function NewAI_TrackGermanConversion(pid, t)
    --  These are exactly the blueprints removed or replaced by the original
    --  commander callbacks. Orders count too, including unfinished construction.
    if (t == 1747989556) then
        NewAI_GermanHimmlerSafe[pid] = false
        NewAI_GermanRommelSafe[pid] = false
    elseif NewAI_HimmlerConverts(t) then
        NewAI_GermanHimmlerSafe[pid] = false
    end
end

function NewAI_Scan(pid)
    local g = CreateGroup()
    local u = nil
    local t = 0
    local order = 0
    local r = 0
    NewAI_HellReset(pid)
    FlushChildHashtable(NewAI_Counts, pid)
    NewAI_Total[pid] = 0
    NewAI_ArmyPoints[pid] = 0
    NewAI_SpawnCount[pid] = 0
    NewAI_Workers[pid] = 0
    NewAI_GermanHimmlerSafe[pid] = true
    NewAI_GermanRommelSafe[pid] = true
    NewAI_GermanRoutePending[pid] = false
    NewAI_PolishRoutePending[pid] = false
    while true do
        if (r > 5) then break end
        NewAI_RoleValue[J88_int(J88_int(pid * 8) + r)] = 0
        r = J88_int(r + 1)
    end
    GroupEnumUnitsOfPlayer(g, Player(pid), nil)
    while true do
        u = FirstOfGroup(g)
        if (u == nil) then break end
        GroupRemoveUnit(g, u)
        if (GetUnitState(u, UNIT_STATE_LIFE) > 0.4050000011920929) then
            t = GetUnitTypeId(u)
            order = GetUnitCurrentOrder(u)
            NewAI_TrackGermanConversion(pid, t)
            NewAI_TrackGermanConversion(pid, order)
            if (((order == 1747993684) or (order == 1747993683)) or (order == 1747993682)) then
                NewAI_GermanRoutePending[pid] = true
            end
            if ((order == 1747993162) or (order == 1747993657)) then
                NewAI_PolishRoutePending[pid] = true
            end
            SaveInteger(NewAI_Counts, pid, t, J88_int(LoadInteger(NewAI_Counts, pid, t) + 1))
            NewAI_ArmyPoints[pid] = J88_int(NewAI_ArmyPoints[pid] + ArmyPoints_UnitValue(u))
            if (LoadInteger(NewAI_Data, t, 3) == 3) then
                NewAI_HellAccumulate(pid, t, GetUnitY(u))
                r = LoadInteger(NewAI_Data, t, 4)
                NewAI_Total[pid] = J88_int(NewAI_Total[pid] + LoadInteger(NewAI_Data, t, 9))
                NewAI_RoleValue[J88_int(J88_int(pid * 8) + r)] = J88_int(NewAI_RoleValue[J88_int(J88_int(pid * 8) + r)] + LoadInteger(NewAI_Data, t, 9))
                NewAI_SpawnCount[pid] = J88_int(NewAI_SpawnCount[pid] + LoadInteger(NewAI_Data, t, 7))
            elseif (LoadInteger(NewAI_Data, t, 3) == 2) then
                NewAI_Workers[pid] = J88_int(NewAI_Workers[pid] + 1)
            end
        end
    end
    DestroyGroup(g)
    g = nil
    u = nil
end

function NewAI_CanBuy(pid, t, actor)
    local p = Player(pid)
    local cap = GetPlayerTechMaxAllowed(p, t)
    local i = 0
    local food = GetFoodUsed(t)
    if (((((t == 1749112624) or (t == 1749112376)) or (t == 1750675762)) or (t == 1749437744)) or (t == 1749435952)) then
        if (not RoundSchedule_IsFinalRound(udg_int_CurRound)) then
            p = nil
            do return false end
        end
    end
    if ((udg_int_CurVsRound < 2) and (((t == 1747993682) or (t == 1747993683)) or (t == 1747993684))) then
        p = nil
        do return false end
    end
    if ((actor ~= nil) and (LoadInteger(NewAI_Data, GetUnitTypeId(actor), 3) == 3)) then
        food = IMaxBJ(0, J88_int(food - GetFoodUsed(GetUnitTypeId(actor))))
    end
    if ((LoadInteger(NewAI_Data, t, 8) ~= 1) or (cap == 0)) then
        p = nil
        do return false end
    end
    if ((cap > 0) and (LoadInteger(NewAI_Counts, pid, t) >= cap)) then
        p = nil
        do return false end
    end
    if (LoadInteger(NewAI_Blocked, pid, t) > NewAI_Tick) then
        p = nil
        do return false end
    end
    if ((GetPlayerState(p, PLAYER_STATE_RESOURCE_GOLD) < LoadInteger(NewAI_Data, t, 1)) or (GetPlayerState(p, PLAYER_STATE_RESOURCE_LUMBER) < LoadInteger(NewAI_Data, t, 2))) then
        p = nil
        do return false end
    end
    if ((food > 0) and (J88_int(GetPlayerState(p, PLAYER_STATE_RESOURCE_FOOD_USED) + food) > GetPlayerState(p, PLAYER_STATE_RESOURCE_FOOD_CAP))) then
        p = nil
        do return false end
    end
    while true do
        if (i >= LoadInteger(NewAI_Data, t, 6)) then break end
        if (GetPlayerTechCount(p, LoadInteger(NewAI_Data, t, J88_int(200 + i)), false) < LoadInteger(NewAI_Data, t, J88_int(300 + i))) then
            p = nil
            do return false end
        end
        i = J88_int(i + 1)
    end
    p = nil
    do return true end
end

function NewAI_SelectNation(pid, actor)
    local i = 0
    local n = 0
    local t = 0
    local chosen = 0
    --  A human may finish the Random selector before the delayed AI startup.
    if (NewAI_Data == nil) then
        ExecuteFunc("NewAI_Init")
    end
    --  Reservoir sampling is exactly uniform over legal real nations. Random is
    --  a selector, not a second chance for its old five-nation sub-list.
    while true do
        if (i >= LoadInteger(NewAI_Data, 1747988568, 5)) then break end
        t = LoadInteger(NewAI_Data, 1747988568, J88_int(100 + i))
        if (((t ~= 1747993925) and (t ~= 0)) and NewAI_CanBuy(pid, t, actor)) then
            n = J88_int(n + 1)
            if (GetRandomInt(1, n) == 1) then
                chosen = t
            end
        end
        i = J88_int(i + 1)
    end
    do return chosen end
end

function NewAI_ResolveRandom()
    local u = GetTriggerUnit()
    local t = NewAI_SelectNation(GetPlayerId(GetOwningPlayer(u)), u)
    if (t ~= 0) then
        u = ReplaceUnitBJ(u, t, bj_UNIT_STATE_METHOD_RELATIVE)
        Nation50_Grant(u)
    end
    u = nil
end

function NewAI_HellPower(pid, t)
    local enemy = udg_int_Opponent[pid]
    local i = 0
    local damage = 0.0
    local survival = 0.0
    local total = 0.0
    local result = 0.0
    if HaveSavedReal(NewAI_HellPowerCache, pid, t) then
        do return LoadReal(NewAI_HellPowerCache, pid, t) end
    end
    if (((enemy >= 0) and (enemy < 8)) and (enemy ~= pid)) then
        total = NewAI_Health[enemy]
    end
    while true do
        if (i >= 8) then break end
        if (total > 0.0) then
            damage = J88_real(J88_real(damage + J88_real(J88_real(LoadReal(NewAI_Data, t, J88_int(520 + i)) * RMaxBJ(0.0, J88_real(NewAI_ArmorHealth[J88_int(J88_int(enemy * 8) + i)] - NewAI_AirArmorHealth[J88_int(J88_int(enemy * 8) + i)]))) / total)) + J88_real(J88_real(LoadReal(NewAI_Data, t, J88_int(550 + i)) * NewAI_AirArmorHealth[J88_int(J88_int(enemy * 8) + i)]) / total))
            survival = J88_real(J88_real(survival + J88_real(RMaxBJ(0.0, J88_real(LoadReal(NewAI_Data, t, J88_int(510 + i)) - LoadReal(NewAI_Data, t, J88_int(560 + i)))) / RMaxBJ(80.0, NewAI_DamageByArmor[J88_int(J88_int(enemy * 8) + i)]))) + J88_real(LoadReal(NewAI_Data, t, J88_int(560 + i)) / RMaxBJ(80.0, NewAI_AADamageByArmor[J88_int(J88_int(enemy * 8) + i)])))
        else
            damage = J88_real(damage + J88_real(J88_real(J88_real(0.8500000238418579 * LoadReal(NewAI_Data, t, J88_int(520 + i))) + J88_real(0.15000000596046448 * LoadReal(NewAI_Data, t, J88_int(550 + i)))) / 8.0))
            survival = J88_real(survival + J88_real(LoadReal(NewAI_Data, t, J88_int(510 + i)) / 160.0))
        end
        i = J88_int(i + 1)
    end
    result = J88_real(J88_real(J88_real(damage * J88_real(0.800000011920929 + RMinBJ(0.6000000238418579, J88_real(LoadReal(NewAI_Data, t, 501) / 1600.0)))) + J88_real(SquareRoot(RMaxBJ(0.0, LoadReal(NewAI_Data, t, 500))) * 2.0)) + J88_real(RMinBJ(40.0, survival) * 8.0))
    SaveReal(NewAI_HellPowerCache, pid, t, result)
    do return result end
end

function NewAI_HellScore(pid, t, source)
    local value = NewAI_HellPower(pid, t)
    local gold = I2R(LoadInteger(NewAI_Data, t, 1))
    local blood = I2R(LoadInteger(NewAI_Data, t, 2))
    local price = J88_real(J88_real(0.20000000298023224 + J88_real(gold / I2R(IMaxBJ(100, GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD))))) + J88_real(blood / I2R(IMaxBJ(1000, GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER)))))
    local role = LoadInteger(NewAI_Data, t, 4)
    local share = J88_real(NewAI_RoleHealth[J88_int(J88_int(pid * 8) + role)] / RMaxBJ(1.0, NewAI_Health[pid]))
    local desired = 0.15000000596046448
    local enemy = udg_int_Opponent[pid]
    if (LoadInteger(NewAI_Data, source, 3) == 3) then
        value = J88_real(value - NewAI_HellPower(pid, source))
    end
    if (role == 1) then
        desired = 0.30000001192092896
    elseif (role == 2) then
        desired = 0.3499999940395355
    elseif (role == 4) then
        desired = 0.05000000074505806
        if (((enemy >= 0) and (enemy < 8)) and (enemy ~= pid)) then
            desired = J88_real(desired + J88_real(J88_real(0.44999998807907104 * NewAI_AirHealth[enemy]) / RMaxBJ(1.0, NewAI_Health[enemy])))
        end
    end
    --  Separate native resource budgets; there is no invented gold/BP exchange.
    --  Free upgrades remain available even when their role trades raw HP for DPS.
    do return J88_real(J88_real(RMaxBJ(1.0, value) * J88_real(1.0 + RMaxBJ(J88_real(-0.3499999940395355), RMinBJ(0.800000011920929, J88_real(desired - share))))) / price) end
end

function NewAI_HellCandidate(actor, t, value)
    local i = 0
    local worst = 0
    local copies = 0
    --  Sixteen distinct legal first actions, followed by at most 256 exact-budget
    --  pairs. Keep actors for upgrades so one structure cannot be upgraded twice.
    while true do
        if (i >= NewAI_HellCandidateCount) then break end
        if ((NewAI_HellType[i] == t) and ((NewAI_HellActor[i] == actor) or (LoadInteger(NewAI_Data, GetUnitTypeId(actor), 3) == 2))) then
            do return end
        end
        if (NewAI_HellType[i] == t) then
            copies = J88_int(copies + 1)
            if (copies >= 2) then
                do return end
            end
        end
        if (NewAI_HellValue[i] < NewAI_HellValue[worst]) then
            worst = i
        end
        i = J88_int(i + 1)
    end
    if (NewAI_HellCandidateCount < 16) then
        i = NewAI_HellCandidateCount
        NewAI_HellCandidateCount = J88_int(i + 1)
    elseif (value > NewAI_HellValue[worst]) then
        i = worst
    else
        do return end
    end
    NewAI_HellActor[i] = actor
    NewAI_HellType[i] = t
    NewAI_HellValue[i] = value
end

function NewAI_HellFood(t, actor)
    if (LoadInteger(NewAI_Data, GetUnitTypeId(actor), 3) == 3) then
        do return IMaxBJ(0, J88_int(GetFoodUsed(t) - GetFoodUsed(GetUnitTypeId(actor)))) end
    end
    do return GetFoodUsed(t) end
end

function NewAI_HellClearCandidates()
    local i = 0
    while true do
        if (i >= 16) then break end
        NewAI_HellActor[i] = nil
        i = J88_int(i + 1)
    end
    NewAI_HellCandidateCount = 0
end

function NewAI_HellPlan(pid)
    local i = 0
    local j = 0
    local a = 0
    local b = 0
    local gold = GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD)
    local blood = GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER)
    local best = J88_int(-1)
    local cap = 0
    local food = J88_int(GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_FOOD_CAP) - GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_FOOD_USED))
    local value = 0.0
    local bestValue = J88_real(-1.0)
    local bonus = 0.0
    local aGold = 0
    local aBlood = 0
    local aFood = 0
    local aKind = 0
    local aRole = 0
    while true do
        if (i >= NewAI_HellCandidateCount) then break end
        a = NewAI_HellType[i]
        if NewAI_CanBuy(pid, a, NewAI_HellActor[i]) then
            value = NewAI_HellValue[i]
            --  No orders are issued inside this planning loop.
            aGold = LoadInteger(NewAI_Data, a, 1)
            aBlood = LoadInteger(NewAI_Data, a, 2)
            aFood = NewAI_HellFood(a, NewAI_HellActor[i])
            aKind = LoadInteger(NewAI_Data, GetUnitTypeId(NewAI_HellActor[i]), 3)
            aRole = LoadInteger(NewAI_Data, a, 4)
            j = 0
            while true do
                if (j >= NewAI_HellCandidateCount) then break end
                b = NewAI_HellType[j]
                cap = GetPlayerTechMaxAllowed(Player(pid), b)
                if (((((J88_int(aGold + LoadInteger(NewAI_Data, b, 1)) <= gold) and (J88_int(aBlood + LoadInteger(NewAI_Data, b, 2)) <= blood)) and (J88_int(aFood + NewAI_HellFood(b, NewAI_HellActor[j])) <= food)) and ((NewAI_HellActor[i] ~= NewAI_HellActor[j]) or (aKind == 2))) and (((a ~= b) or (cap < 0)) or (J88_int(LoadInteger(NewAI_Counts, pid, b) + 2) <= cap))) then
                    bonus = J88_real(0.6499999761581421 * NewAI_HellValue[j])
                    if (aRole ~= LoadInteger(NewAI_Data, b, 4)) then
                        bonus = J88_real(bonus * 1.149999976158142)
                    end
                    if (J88_real(NewAI_HellValue[i] + bonus) > value) then
                        value = J88_real(NewAI_HellValue[i] + bonus)
                    end
                end
                j = J88_int(j + 1)
            end
            if (value > bestValue) then
                bestValue = value
                best = i
            end
        end
        i = J88_int(i + 1)
    end
    if (best >= 0) then
        NewAI_BestType = NewAI_HellType[best]
        NewAI_BestUnit = NewAI_HellActor[best]
        NewAI_BestScore = bestValue
    end
    i = 0
    while true do
        if (i >= NewAI_HellCandidateCount) then break end
        NewAI_HellActor[i] = nil
        i = J88_int(i + 1)
    end
end

function NewAI_HellSiteDistance(pid, role, x, y, distance)
    local area = udg_PlayerLocationArray[pid]
    local enemy = udg_int_Opponent[pid]
    local targetX = J88_real(GetRectMinX(area) + 64.0)
    local targetY = GetRectCenterY(area)
    local shift = 0.0
    if ((role == 1) or (role == 2)) then
        targetX = J88_real(GetRectMaxX(area) - 64.0)
    elseif (role == 4) then
        targetX = GetRectCenterX(area)
    end
    if ((((enemy >= 0) and (enemy < 8)) and (enemy ~= pid)) and (NewAI_Health[enemy] > 0.0)) then
        shift = J88_real(J88_real(J88_real(NewAI_FormationY[enemy] / NewAI_Health[enemy]) - GetRectCenterY(udg_PlayerLocationArray[enemy])) / RMaxBJ(1.0, J88_real(GetRectMaxY(udg_PlayerLocationArray[enemy]) - GetRectMinY(udg_PlayerLocationArray[enemy]))))
        targetY = J88_real(targetY + J88_real(RMaxBJ(J88_real(-0.3499999940395355), RMinBJ(0.3499999940395355, shift)) * J88_real(GetRectMaxY(area) - GetRectMinY(area))))
    end
    area = nil
    --  The map's spawn sorter takes high-X blueprints first: tanks/infantry
    --  screen the guns; AA sits between them, aligned to the enemy's center mass.
    do return J88_real(J88_real(J88_real(J88_real(8.0 * J88_real(x - targetX)) * J88_real(x - targetX)) + J88_real(J88_real(0.3499999940395355 * J88_real(y - targetY)) * J88_real(y - targetY))) + J88_real(0.0020000000949949026 * distance)) end
end

function NewAI_Score(pid, t)
    local role = LoadInteger(NewAI_Data, t, 4)
    local enemy = udg_int_Opponent[pid]
    local target = 0.15000000596046448
    local current = J88_real(I2R(NewAI_RoleValue[J88_int(J88_int(pid * 8) + role)]) / I2R(IMaxBJ(1, NewAI_Total[pid])))
    local enemyTotal = 1.0
    local result = 0.0
    if ((enemy >= 0) and (enemy < 8)) then
        enemyTotal = I2R(IMaxBJ(1, NewAI_Total[enemy]))
    end
    if (role == 1) then
        target = 0.4000000059604645
    elseif (role == 2) then
        target = 0.25
    elseif (role == 4) then
        target = 0.07000000029802322
    elseif (role == 5) then
        target = 0.12999999523162842
    end
    if (NewAI_Level[pid] == 1) then
        if (role == 1) then
            target = 0.6499999761581421
        elseif (role == 2) then
            target = 0.15000000596046448
        else
            target = 0.07000000029802322
        end
    elseif ((((NewAI_Level[pid] == 3) and (enemy >= 0)) and (enemy < 8)) and (enemy ~= pid)) then
        if (role == 3) then
            target = J88_real(target + J88_real(J88_real(0.4000000059604645 * I2R(NewAI_RoleValue[J88_int(J88_int(enemy * 8) + 2)])) / enemyTotal))
        elseif (role == 4) then
            target = J88_real(target + J88_real(J88_real(0.6499999761581421 * I2R(NewAI_RoleValue[J88_int(J88_int(enemy * 8) + 5)])) / enemyTotal))
        elseif (role == 2) then
            target = J88_real(target + J88_real(J88_real(0.20000000298023224 * I2R(NewAI_RoleValue[J88_int(J88_int(enemy * 8) + 1)])) / enemyTotal))
        end
    end
    --  Diversity and composition are heuristics, not a claim of measured power.
    result = J88_real(100.0 + J88_real(J88_real(target - current) * 160.0))
    result = J88_real(result / J88_real(1.0 + J88_real(0.6499999761581421 * I2R(LoadInteger(NewAI_Counts, pid, t)))))
    result = J88_real(result + I2R(NewAI_Random(pid, 16)))
    if ((NewAI_Total[pid] == 0) and (role == 1)) then
        result = J88_real(result + 150.0)
    end
    --  Spend earned Blood Pts as well as gold once the relevant tech is unlocked.
    if (LoadInteger(NewAI_Data, t, 2) > 0) then
        result = J88_real(result + 20.0)
    end
    --  Affordability and final-round tech were checked before scoring.
    --  Prioritize each ship only with BP already available.
    if ((t == 1750675762) and RoundSchedule_IsFinalRound(udg_int_CurRound)) then
        result = J88_real(result + 1000.0)
    end
    do return result end
end

function NewAI_PointFree(x, y)
    local g = nil
    local u = nil
    local ok = true
    if (LoadInteger(NewAI_SiteBlocked, R2I(x), R2I(y)) > NewAI_Tick) then
        do return false end
    end
    --  Query the centres of all four 32-wide cells in the 2x2 footprint.
    --  Sampling its outer +32 edge can hit a neighbouring blocked path cell.
    if (((IsTerrainPathable(J88_real(x - 16.0), J88_real(y - 16.0), PATHING_TYPE_BUILDABILITY) or IsTerrainPathable(J88_real(x - 16.0), J88_real(y + 16.0), PATHING_TYPE_BUILDABILITY)) or IsTerrainPathable(J88_real(x + 16.0), J88_real(y - 16.0), PATHING_TYPE_BUILDABILITY)) or IsTerrainPathable(J88_real(x + 16.0), J88_real(y + 16.0), PATHING_TYPE_BUILDABILITY)) then
        do return false end
    end
    g = CreateGroup()
    GroupEnumUnitsInRange(g, x, y, 192.0, nil)
    while true do
        u = FirstOfGroup(g)
        if ((u == nil) or (not ok)) then break end
        GroupRemoveUnit(g, u)
        if (((IsUnitType(u, UNIT_TYPE_STRUCTURE) and (GetUnitState(u, UNIT_STATE_LIFE) > 0.4050000011920929)) and (RAbsBJ(J88_real(GetUnitX(u) - x)) < 64.0)) and (RAbsBJ(J88_real(GetUnitY(u) - y)) < 64.0)) then
            ok = false
        end
    end
    DestroyGroup(g)
    g = nil
    u = nil
    do return ok end
end

function NewAI_FindSite(pid, role)
    local area = udg_PlayerLocationArray[pid]
    local cols = 0
    local rows = 0
    local count = 0
    local i = 0
    local slot = 0
    local col = 0
    local x = 0.0
    local y = 0.0
    local startX = 0.0
    local startY = 0.0
    local dx = 0.0
    local dy = 0.0
    local distance = 0.0
    local bestDistance = 1000000000.0
    local bestSlot = J88_int(-1)
    local actorX = 0.0
    local actorY = 0.0
    if (area == nil) then
        do return false end
    end
    --  Blueprints/HQs use the 64-wide 2x2Default footprint and builders fly.
    --  Match that footprint; the old gaps exhausted the usable terrain early.
    --  Match the 32-modulo-64 centres of the map's eight original HQs.
    startX = J88_real(GetRectMinX(area) + 64.0)
    startY = J88_real(GetRectMinY(area) + 64.0)
    startX = J88_real(startX + I2R(ModuloInteger(J88_int(32 - R2I(startX)), 64)))
    startY = J88_real(startY + I2R(ModuloInteger(J88_int(32 - R2I(startY)), 64)))
    if ((startX > J88_real(GetRectMaxX(area) - 64.0)) or (startY > J88_real(GetRectMaxY(area) - 64.0))) then
        area = nil
        do return false end
    end
    cols = J88_int(R2I(J88_real(J88_real(J88_real(GetRectMaxX(area) - 64.0) - startX) / 64.0)) + 1)
    rows = J88_int(R2I(J88_real(J88_real(J88_real(GetRectMaxY(area) - 64.0) - startY) / 64.0)) + 1)
    count = J88_int(cols * rows)
    if ((cols < 1) or (rows < 1)) then
        area = nil
        do return false end
    end
    --  Placement queries do not move the builder or yield.
    if (NewAI_BuildSiteActor ~= nil) then
        actorX = GetUnitX(NewAI_BuildSiteActor)
        actorY = GetUnitY(NewAI_BuildSiteActor)
    end
    while true do
        if (i >= count) then break end
        slot = ModuloInteger(J88_int(NewAI_SlotCursor[pid] + i), count)
        col = J88_div(slot, rows)
        --  The original spawn sorter deploys high-X blueprints first.
        if ((role == 1) or (role == 2)) then
            col = J88_int(J88_int(cols - 1) - col)
        end
        x = J88_real(startX + J88_real(I2R(col) * 64.0))
        y = J88_real(startY + J88_real(I2R(ModuloInteger(slot, rows)) * 64.0))
        if (NewAI_BuildSiteActor == nil) then
            distance = I2R(i)
        else
            dx = J88_real(x - actorX)
            dy = J88_real(y - actorY)
            distance = J88_real(J88_real(dx * dx) + J88_real(dy * dy))
        end
        if ((NewAI_Level[pid] == 4) and (role > 0)) then
            distance = NewAI_HellSiteDistance(pid, role, x, y, distance)
        end
        if ((distance < bestDistance) and NewAI_PointFree(x, y)) then
            NewAI_BuildX = x
            NewAI_BuildY = y
            bestSlot = slot
            bestDistance = distance
            if (NewAI_BuildSiteActor == nil) then
                NewAI_SlotCursor[pid] = ModuloInteger(J88_int(slot + 1), count)
                area = nil
                do return true end
            end
        end
        i = J88_int(i + 1)
    end
    area = nil
    if (bestSlot >= 0) then
        NewAI_SlotCursor[pid] = ModuloInteger(J88_int(bestSlot + 1), count)
        do return true end
    end
    do return false end
end

function NewAI_EconomyScore(t, source)
    local delta = J88_int(LoadInteger(ArmyEconomy_Types, t, 0) + J88_div(LoadInteger(ArmyEconomy_Types, t, 1), 10))
    local remaining = J88_real(I2R(IMaxBJ(0, J88_int(RoundSchedule_FinalRound - udg_int_CurRound))) / I2R(J88_int(RoundSchedule_FinalRound - 1)))
    if (t == 1749242932) then
        delta = 150
    end
    --  Both construction and upgrading add their actual incremental payment.
    --  Squad spawn counts and combat Kill Points do not enter Army Points.
    do return J88_real(RMaxBJ(J88_real(-45.0), RMinBJ(45.0, J88_real(I2R(delta) * 0.11999999731779099))) * remaining) end
end

function NewAI_GermanRouteAllowed(pid, t, actor)
    if (udg_int_CurVsRound < 2) then
        do return false end
    end
    if NewAI_GermanRoutePending[pid] then
        do return false end
    end
    if (((GetUnitTypeId(actor) ~= 1747989296) or (GetUnitCurrentOrder(actor) ~= 0)) or (GetUnitState(actor, UNIT_STATE_LIFE) <= 0.4050000011920929)) then
        do return false end
    end
    if ((LoadInteger(NewAI_Counts, pid, 1747989058) == 0) or (J88_int(J88_int(LoadInteger(NewAI_Counts, pid, 1747993684) + LoadInteger(NewAI_Counts, pid, 1747993683)) + LoadInteger(NewAI_Counts, pid, 1747993682)) > 0)) then
        do return false end
    end
    if (t == 1747993683) then
        if (not NewAI_GermanHimmlerSafe[pid]) then
            do return false end
        end
    elseif (t == 1747993682) then
        if (not NewAI_GermanRommelSafe[pid]) then
            do return false end
        end
    elseif (t ~= 1747993684) then
        do return false end
    end
    do return NewAI_CanBuy(pid, t, actor) end
end

function NewAI_PickGermanRoute(pid, actor)
    local i = 0
    local slot = 0
    local t = 0
    --  Two Himmler, two Rommel, one Hitler in each unrestricted five-choice
    --  cycle. A synchronized random starting slot varies matches. Failed or
    --  merely considered orders never advance the cycle.
    while true do
        if (i >= 5) then break end
        slot = ModuloInteger(J88_int(NewAI_GermanRouteCursor + i), 5)
        if ((slot == 0) or (slot == 2)) then
            t = 1747993683
        elseif ((slot == 1) or (slot == 3)) then
            t = 1747993682
        else
            t = 1747993684
        end
        if NewAI_GermanRouteAllowed(pid, t, actor) then
            do return t end
        end
        i = J88_int(i + 1)
    end
    do return 0 end
end

function NewAI_KeepGermanOptions(pid, t)
    --  A busy, undecided HQ must not make its own builder buy SS/Wehrmacht
    --  first and thereby force the later safety check back to Hitler. Other
    --  compatible purchases can proceed before Round 2 and while the HQ is busy.
    if (LoadInteger(NewAI_Counts, pid, 1747989296) == 0) then
        do return false end
    end
    if (J88_int(J88_int(LoadInteger(NewAI_Counts, pid, 1747993684) + LoadInteger(NewAI_Counts, pid, 1747993683)) + LoadInteger(NewAI_Counts, pid, 1747993682)) > 0) then
        do return false end
    end
    if ((NewAI_HimmlerConverts(t) and NewAI_GermanHimmlerSafe[pid]) and ((udg_int_CurVsRound < 2) or NewAI_CanBuy(pid, 1747993683, nil))) then
        do return true end
    end
    do return (((t == 1747989556) and NewAI_GermanRommelSafe[pid]) and ((udg_int_CurVsRound < 2) or NewAI_CanBuy(pid, 1747993682, nil))) end
end

function NewAI_PolishRouteScore(pid, t, actor)
    local blood = GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER)
    --  Preserve the domestic builder before a mutually exclusive HQ upgrade.
    --  Leave a BP reserve for immediate units after buying the route itself.
    if (((((actor == nil) or (GetUnitTypeId(actor) ~= 1747990604)) or (GetUnitCurrentOrder(actor) ~= 0)) or (GetUnitState(actor, UNIT_STATE_LIFE) <= 0.4050000011920929)) or NewAI_PolishRoutePending[pid]) then
        do return J88_real(-1.0) end
    end
    if ((((udg_int_CurVsRound < 3) or (LoadInteger(NewAI_Counts, pid, 1747993153) == 0)) or (J88_int(LoadInteger(NewAI_Counts, pid, 1747993162) + LoadInteger(NewAI_Counts, pid, 1747993657)) > 0)) or (not NewAI_CanBuy(pid, t, actor))) then
        do return J88_real(-1.0) end
    end
    if (((t == 1747993162) and (blood >= 16000)) and (NewAI_ArmyPoints[pid] >= 6000)) then
        do return 1600.0 end
    elseif ((t == 1747993657) and (blood >= 8000)) then
        do return 1500.0 end
    end
    do return J88_real(-1.0) end
end

function NewAI_NoteOrder(pid, actor, t, ok)
    if ok then
        NewAI_OrderedThisThink = true
        if (((t == 1747993684) or (t == 1747993683)) or (t == 1747993682)) then
            NewAI_GermanRouteCursor = ModuloInteger(J88_int(NewAI_GermanRouteCursor + 1), 5)
        end
        --  Track builder movement for timeout recovery. An unrelated HQ or
        --  blueprint upgrade must not lock all other actors in this seat.
        if (LoadInteger(NewAI_Data, GetUnitTypeId(actor), 3) == 2) then
