            NewAI_BusySince[pid] = NewAI_Tick
            NewAI_BuildTargetActor[pid] = actor
            NewAI_BuildTargetX[pid] = NewAI_BuildX
            NewAI_BuildTargetY[pid] = NewAI_BuildY
        end
        NewAI_Purchases[pid] = J88_int(NewAI_Purchases[pid] + 1)
        NewAI_Status[pid] = J88_concat("ordered ", LoadStr(NewAI_Data, t, 10))
        if (NewAI_Level[pid] == 1) then
            NewAI_NextThink[pid] = J88_int(NewAI_Tick + 2)
        else
            NewAI_NextThink[pid] = J88_int(NewAI_Tick + 1)
        end
    else
        SaveInteger(NewAI_Blocked, pid, t, J88_int(NewAI_Tick + 5))
        NewAI_Failures[pid] = J88_int(NewAI_Failures[pid] + 1)
