    end
end

function NewAI_Consider(pid, actor)
    local source = GetUnitTypeId(actor)
    local kind = LoadInteger(NewAI_Data, source, 3)
    local count = LoadInteger(NewAI_Data, source, 5)
    local i = 0
    local t = 0
    local projectedSpawn = 0
    local score = 0.0
    if ((GetUnitCurrentOrder(actor) ~= 0) or (GetUnitState(actor, UNIT_STATE_LIFE) <= 0.4050000011920929)) then
        do return end
    end
    if (source == 1747988568) then
        t = NewAI_SelectNation(pid, actor)
        if (t ~= 0) then
            NewAI_BestType = t
            NewAI_BestUnit = actor
            NewAI_BestScore = 5000.0
        end
        do return end
    end
    if (source == 1747989848) then
        t = France54_PickRoute(pid, actor)
        if (t ~= 0) then
            score = 5000.0
            if (NewAI_Level[pid] == 4) then
                score = J88_real(score + 1000000.0)
            end
            if (score > NewAI_BestScore) then
                NewAI_BestType = t
                NewAI_BestUnit = actor
                NewAI_BestScore = score
            end
        end
        do return end
    end
    while true do
        if (i >= count) then break end
        t = LoadInteger(NewAI_Data, source, J88_int(100 + i))
        if NewAI_CanBuy(pid, t, actor) then
            score = J88_real(-1.0)
            if ((source == 1747989296) and (((t == 1747993684) or (t == 1747993683)) or (t == 1747993682))) then
                --  Train the normal builder before spending a turn on a route.
                --  Preserve a normal German builder before selecting any route.
                if ((LoadInteger(NewAI_Counts, pid, 1747989058) > 0) and (J88_int(J88_int(LoadInteger(NewAI_Counts, pid, 1747993684) + LoadInteger(NewAI_Counts, pid, 1747993683)) + LoadInteger(NewAI_Counts, pid, 1747993682)) == 0)) then
                    if (not NewAI_GermanRouteAllowed(pid, NewAI_GermanRoute[pid], actor)) then
                        NewAI_GermanRoute[pid] = NewAI_PickGermanRoute(pid, actor)
                    end
                    if (t == NewAI_GermanRoute[pid]) then
                        score = 2500.0
                    end
                end
            elseif ((t == 1749233714) or (t == 1749828174)) then
                if (NewAI_Workers[pid] > 0) then
                    score = 1900.0
                end
            elseif ((t == 1749954866) or (t == 1749889330)) then
                if ((NewAI_Workers[pid] > 0) and (GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER) >= 12000)) then
                    score = 1900.0
                end
            elseif ((kind == 1) and (LoadInteger(NewAI_Data, t, 3) == 2)) then
                if (LoadInteger(NewAI_Counts, pid, t) == 0) then
                    score = J88_real(2000.0 + I2R(NewAI_Random(pid, 100)))
                end
            elseif (t == ZK_HQ) then
                score = Zhukov_AIScore(pid)
            elseif ((source == 1747990604) and ((t == 1747993162) or (t == 1747993657))) then
                score = NewAI_PolishRouteScore(pid, t, actor)
            elseif (((kind == 1) and (LoadInteger(NewAI_Data, t, 3) == 1)) and (NewAI_Workers[pid] == 0)) then
                --  Finish an inherited faction selection, e.g. China -> Republic.
                --  Catalog only supplies such children when no builder is trainable.
                score = J88_real(3000.0 + I2R(NewAI_Random(pid, 100)))
            elseif (((kind == 2) or (kind == 3)) and (LoadInteger(NewAI_Data, t, 3) == 3)) then
                projectedSpawn = J88_int(NewAI_SpawnCount[pid] + LoadInteger(NewAI_Data, t, 7))
                if (kind == 3) then
                    projectedSpawn = J88_int(projectedSpawn - LoadInteger(NewAI_Data, source, 7))
                end
                if (((LoadInteger(NewAI_Data, t, 7) > 0) and (projectedSpawn < 850)) and (not NewAI_KeepGermanOptions(pid, t))) then
                    if ((kind ~= 2) or NewAI_BuildSpaceAvailable) then
                        score = NewAI_Score(pid, t)
                        if (NewAI_Level[pid] == 4) then
                            score = NewAI_HellScore(pid, t, source)
                        end
                        if ((kind == 3) and (NewAI_Level[pid] ~= 4)) then
                            --  Conservative upgrade affordability: engine checks the
                            --  actual upgrade rules, all original finish hooks run.
                            score = J88_real(score * 0.800000011920929)
                        end
                        score = RMaxBJ(1.0, J88_real(score + NewAI_EconomyScore(t, source)))
                        if (NewAI_Level[pid] == 4) then
                            NewAI_HellCandidate(actor, t, score)
                        end
                    end
                end
            end
            if (((kind == 1) and (NewAI_Level[pid] == 4)) and (score > 0.0)) then
                score = J88_real(score + 1000000.0)
            end
            if (score > NewAI_BestScore) then
                NewAI_BestScore = score
                NewAI_BestType = t
                NewAI_BestUnit = actor
            end
        end
        i = J88_int(i + 1)
    end
end

function NewAI_ConsiderActor()
    NewAI_Consider(NewAI_CurrentPid, NewAI_EvaluateActor)
end

function NewAI_OnRommelReady()
    local pid = GetPlayerId(GetTriggerPlayer())
    if (((pid < 0) or (pid > 7)) or (not NewAI_Ready)) then
        do return end
    end
    NewAI_Busy[pid] = nil
    NewAI_BusySince[pid] = 0
    NewAI_BuildTargetActor[pid] = nil
    NewAI_BuildTargetX[pid] = 0.0
    NewAI_BuildTargetY[pid] = 0.0
    NewAI_BuildSpaceState[pid] = 0
    NewAI_GermanRoute[pid] = 1747993682
    NewAI_GermanRoutePending[pid] = false
    NewAI_NextThink[pid] = NewAI_Tick
    if (NewAI_Blocked ~= nil) then
        FlushChildHashtable(NewAI_Blocked, pid)
    end
    NewAI_Scan(pid)
    NewAI_Status[pid] = "Rommel ready; rebuilding with refunded resources"
end

function NewAI_Think()
    local pid = NewAI_CurrentPid
    local enemy = udg_int_Opponent[pid]
    local g = nil
    local u = nil
    local kind = 0
    local savedCursor = 0
    local ok = false
    NewAI_OrderedThisThink = false
    if (((((not NewAI_Controlled[pid]) or (not NewAI_Preparing)) or NewAI_Paused) or DifficultyChoice_Pending) or (NewAI_Tick < NewAI_NextThink[pid])) then
        do return end
    end
    if (TimerGetRemaining(udg_timer_PreRoundCount) < 4.0) then
        do return end
    end
    NewAI_Status[pid] = "checking economy and build sites"
    --  Let this builder finish walking/building, while other idle blueprints
    --  remain eligible for upgrades. Never replace an actor's active order.
    if (NewAI_Busy[pid] ~= nil) then
        if (GetUnitCurrentOrder(NewAI_Busy[pid]) ~= 0) then
            --  A native placement order can be accepted yet never reach its site.
            --  Stop only our own timed-out builder, during preparation.
            if ((J88_int(NewAI_Tick - NewAI_BusySince[pid]) >= 15) and (LoadInteger(NewAI_Data, GetUnitTypeId(NewAI_Busy[pid]), 3) == 2)) then
                if (NewAI_BuildTargetActor[pid] == NewAI_Busy[pid]) then
                    SaveInteger(NewAI_SiteBlocked, R2I(NewAI_BuildTargetX[pid]), R2I(NewAI_BuildTargetY[pid]), J88_int(NewAI_Tick + 30))
                    NewAI_BuildTargetActor[pid] = nil
                end
                IssueImmediateOrder(NewAI_Busy[pid], "stop")
                NewAI_Status[pid] = "builder timeout; selecting another site"
                NewAI_Busy[pid] = nil
            end
        else
            NewAI_Busy[pid] = nil
        end
    end
    if (NewAI_Level[pid] == 1) then
        NewAI_NextThink[pid] = J88_int(NewAI_Tick + 2)
    else
        NewAI_NextThink[pid] = J88_int(NewAI_Tick + 1)
    end
    NewAI_Scan(pid)
    if (((enemy >= 0) and (enemy < 8)) and (enemy ~= pid)) then
        NewAI_Scan(enemy)
    end
    --  Enemy profiles are now current. Cache only within this decision;
    --  later purchases, players and rounds always recalculate combat scores.
    FlushParentHashtable(NewAI_HellPowerCache)
    --  A build with no usable site is not a purchase candidate. Otherwise it
    --  can repeatedly outrank valid upgrades and leave Blood Pts unspent.
    savedCursor = NewAI_SlotCursor[pid]
    NewAI_BuildSiteActor = nil
    NewAI_BuildSpaceAvailable = NewAI_FindSite(pid, 0)
    if NewAI_BuildSpaceAvailable then
        NewAI_BuildSpaceState[pid] = 1
    else
        NewAI_BuildSpaceState[pid] = 2
    end
    NewAI_SlotCursor[pid] = savedCursor
    NewAI_BestUnit = nil
    NewAI_BestType = 0
    NewAI_BestScore = 0.0
    NewAI_HellCandidateCount = 0
    g = CreateGroup()
    GroupEnumUnitsOfPlayer(g, Player(pid), nil)
    while true do
        u = FirstOfGroup(g)
        if (u == nil) then break end
        GroupRemoveUnit(g, u)
        if (((NewAI_Busy[pid] == nil) and (LoadInteger(NewAI_Data, GetUnitTypeId(u), 3) == 2)) and (GetUnitCurrentOrder(u) ~= 0)) then
            NewAI_Busy[pid] = u
            NewAI_BusySince[pid] = NewAI_Tick
        end
        --  Long late-game rosters no longer share one actor-evaluation budget.
        NewAI_EvaluateActor = u
        ExecuteFunc("NewAI_ConsiderActor")
    end
    DestroyGroup(g)
    g = nil
    u = nil
    NewAI_EvaluateActor = nil
    if ((NewAI_Level[pid] == 4) and (NewAI_BestScore < 1000000.0)) then
        NewAI_HellPlan(pid)
    end
    if (NewAI_BestUnit ~= nil) then
        kind = LoadInteger(NewAI_Data, GetUnitTypeId(NewAI_BestUnit), 3)
        if (kind == 2) then
            --  Builders fly at their native speed. Select the nearest free site
            --  instead of repeatedly crossing the base when a role changes.
            NewAI_BuildSiteActor = NewAI_BestUnit
            if NewAI_FindSite(pid, LoadInteger(NewAI_Data, NewAI_BestType, 4)) then
                ok = IssueBuildOrderById(NewAI_BestUnit, NewAI_BestType, NewAI_BuildX, NewAI_BuildY)
                if (not ok) then
                    SaveInteger(NewAI_SiteBlocked, R2I(NewAI_BuildX), R2I(NewAI_BuildY), J88_int(NewAI_Tick + 30))
                end
                NewAI_NoteOrder(pid, NewAI_BestUnit, NewAI_BestType, ok)
            else
                SaveInteger(NewAI_Blocked, pid, NewAI_BestType, J88_int(NewAI_Tick + 4))
                NewAI_Status[pid] = "no free build site; saving or upgrading"
            end
            NewAI_BuildSiteActor = nil
        elseif (((NewAI_BestType == 1747993684) or (NewAI_BestType == 1747993683)) or (NewAI_BestType == 1747993682)) then
            --  Recheck the actual army and pending orders at the point of issue.
            NewAI_Scan(pid)
            if NewAI_GermanRouteAllowed(pid, NewAI_BestType, NewAI_BestUnit) then
                ok = IssueImmediateOrderById(NewAI_BestUnit, NewAI_BestType)
                NewAI_NoteOrder(pid, NewAI_BestUnit, NewAI_BestType, ok)
            else
                NewAI_GermanRoute[pid] = 0
                NewAI_Status[pid] = "preserving army; reconsidering commander"
            end
        elseif ((NewAI_BestType == 1747993162) or (NewAI_BestType == 1747993657)) then
            NewAI_Scan(pid)
            if (NewAI_PolishRouteScore(pid, NewAI_BestType, NewAI_BestUnit) > 0.0) then
                ok = IssueImmediateOrderById(NewAI_BestUnit, NewAI_BestType)
                NewAI_NoteOrder(pid, NewAI_BestUnit, NewAI_BestType, ok)
            end
        else
            ok = IssueImmediateOrderById(NewAI_BestUnit, NewAI_BestType)
            NewAI_NoteOrder(pid, NewAI_BestUnit, NewAI_BestType, ok)
        end
    else
        if (not NewAI_BuildSpaceAvailable) then
            NewAI_Status[pid] = "no build site; no affordable idle upgrade"
        elseif (NewAI_Busy[pid] ~= nil) then
            NewAI_Status[pid] = "builder busy; no affordable idle upgrade"
        else
            NewAI_Status[pid] = "saving resources / awaiting tech or orders"
        end
    end
    NewAI_HellClearCandidates()
    NewAI_LastThink[pid] = NewAI_Tick
    NewAI_BestUnit = nil
end

function NewAI_SetControl(pid)
    if (((pid < 0) or (pid > 7)) or NewAI_Controlled[pid]) then
        do return end
    end
    NewAI_Controlled[pid] = true
    SetPlayerName(Player(pid), J88_concat("[AI] ", GetPlayerName(Player(pid))))
    SetPlayerName(Player(J88_int(pid + 9)), GetPlayerName(Player(pid)))
    SetPlayerHandicap(Player(J88_int(pid + 9)), 1.0)
    SetPlayerHandicapDamage(Player(J88_int(pid + 9)), 1.0)
    ForceAddPlayer(udg_AllPlayers, Player(pid))
    NewAI_Status[pid] = "takeover ready"
    NewAI_NextThink[pid] = NewAI_Tick
end

function NewAI_OnLeave()
    if ((NewAI_LeavePid >= 0) and (NewAI_LeavePid < 8)) then
        NewAI_SetControl(NewAI_LeavePid)
        DisplayTextToForce(GetPlayersAll(), J88_concat(J88_concat("[AI] Player ", I2S(J88_int(NewAI_LeavePid + 1))), " left: existing army and resources retained; AI continues next preparation."))
    end
end

function NewAI_OnBattle()
    NewAI_Preparing = false
end

function NewAI_OnPrepare()
    local pid = 0
    NewAI_Preparing = true
    if (NewAI_RecoveryData ~= nil) then
        FlushParentHashtable(NewAI_RecoveryData)
    end
    while true do
        if (pid >= 8) then break end
        NewAI_NextThink[pid] = NewAI_Tick
        NewAI_BusySince[pid] = NewAI_Tick
        NewAI_Status[pid] = "planning"
        pid = J88_int(pid + 1)
    end
    if (NewAI_SoloTest and (NewAI_PrepSeconds >= 15)) then
        TimerStart(udg_timer_PreRoundCount, I2R(NewAI_PrepSeconds), false, nil)
    end
    DifficultyChoice_OnPrepare()
end

function NewAI_OnTick()
    NewAI_Tick = J88_int(NewAI_Tick + 1)
    if (((not NewAI_Ready) or NewAI_Paused) or DifficultyChoice_Pending) then
        do return end
    end
    if (not NewAI_Preparing) then
        NewAI_CurrentPid = 0
        while true do
            if (NewAI_CurrentPid >= 8) then break end
            if NewAI_Controlled[NewAI_CurrentPid] then
                ExecuteFunc("NewAI_RecoverySeat")
                ExecuteFunc("Carrier_AIThink")
            end
            NewAI_CurrentPid = J88_int(NewAI_CurrentPid + 1)
        end
        do return end
    end
    NewAI_CurrentPid = 0
    while true do
        if (NewAI_CurrentPid >= 8) then break end
        --  Separate JASS execution budgets for each seat; no sleeps or local state.
        ExecuteFunc("NewAI_Think")
        if ((NewAI_OrderedThisThink and (NewAI_Level[NewAI_CurrentPid] >= 2)) and (udg_int_CurVsRound >= 3)) then
            --  Later preparations can receive much larger BP payouts. Permit a
            --  second idle actor to buy in this tick, with a fresh resource/army
            --  scan. Accepted native orders are never replaced or fast-finished.
            NewAI_NextThink[NewAI_CurrentPid] = NewAI_Tick
            ExecuteFunc("NewAI_Think")
        end
        Mac70_AIUpgrade(NewAI_CurrentPid)
        NewAI_CurrentPid = J88_int(NewAI_CurrentPid + 1)
    end
end

function NewAI_StatusText(p)
    local pid = 0
    local phase = "battle"
    if NewAI_Preparing then
        phase = "preparation"
    end
    DisplayTimedTextToPlayer(p, 0.0, 0.0, 20.0, J88_concat(J88_concat(J88_concat(J88_concat(J88_concat("[WW2 BT 1.0.3] ", phase), " | round "), I2S(udg_int_CurRound)), " | seed "), I2S(NewAI_Seed)))
    while true do
        if (pid >= 8) then break end
        if NewAI_Controlled[pid] then
            NewAI_Scan(pid)
            DisplayTimedTextToPlayer(p, 0.0, 0.0, 20.0, J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat(J88_concat("P", I2S(J88_int(pid + 1))), " L"), I2S(NewAI_Level[pid])), " gold="), I2S(GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_GOLD))), " blood="), I2S(GetPlayerState(Player(pid), PLAYER_STATE_RESOURCE_LUMBER))), " points="), I2S(NewAI_ArmyPoints[pid])), " units="), I2S(NewAI_SpawnCount[pid])), " orders="), I2S(NewAI_Purchases[pid])), " rejected="), I2S(NewAI_Failures[pid])), " site="), I2S(NewAI_BuildSpaceState[pid])), " idleTicks="), I2S(J88_int(NewAI_Tick - NewAI_LastThink[pid]))), " "), NewAI_Status[pid]))
        end
        pid = J88_int(pid + 1)
    end
end

function NewAI_OnChat()
    local p = GetTriggerPlayer()
    local s = StringCase(GetEventPlayerChatString(), false)
    local n = 0
    local pid = 0
    if ((s == "-ai") or (s == "-ai help")) then
        DisplayTimedTextToPlayer(p, 0.0, 0.0, 30.0, "[AI] -ai status | Solo test only: -ai level 1/2/3/4, -ai seed 1..65535, -ai pause, -ai resume, -ai take 1..8, -ai prep 15..180 (0=default, next round). Opening dialog selects difficulty; all levels use normal income and unit stats.")
    elseif (s == "-ai status") then
        NewAI_StatusText(p)
    elseif ((not NewAI_SoloTest) or (GetPlayerId(p) ~= NewAI_Host)) then
        DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, "[AI] Test controls are available only when the game STARTED with exactly one human.")
    elseif (s == "-ai pause") then
        NewAI_Paused = true
        DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, "[AI] New planning paused; accepted orders and battles continue.")
    elseif (s == "-ai resume") then
        NewAI_Paused = false
        DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, "[AI] Planning resumed.")
    elseif (SubString(s, 0, 10) == "-ai level ") then
        n = S2I(SubString(s, 10, StringLength(s)))
        if ((n >= 1) and (n <= 4)) then
            DifficultyChoice_Level = n
            while true do
                if (pid >= 8) then break end
                NewAI_Level[pid] = n
                pid = J88_int(pid + 1)
            end
            DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, J88_concat(J88_concat("[AI] Level ", I2S(n)), ": changes composition and think rate; no resource/stat bonuses."))
        end
    elseif (SubString(s, 0, 9) == "-ai seed ") then
        n = S2I(SubString(s, 9, StringLength(s)))
        if ((n >= 1) and (n <= 65535)) then
            NewAI_Seed = n
            NewAI_GermanRouteCursor = ModuloInteger(n, 5)
            while true do
                if (pid >= 8) then break end
                NewAI_Rng[pid] = ModuloInteger(J88_int(n + J88_int(pid * 7919)), 65536)
                pid = J88_int(pid + 1)
            end
            DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, "[AI] Decision seed updated; the map's battle randomness is unchanged.")
        end
    elseif (SubString(s, 0, 9) == "-ai take ") then
        n = S2I(SubString(s, 9, StringLength(s)))
        if ((n >= 1) and (n <= 8)) then
            NewAI_SetControl(J88_int(n - 1))
            DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, J88_concat(J88_concat("[AI] Test takeover enabled for P", I2S(n)), "; this lasts for this match."))
        end
    elseif (SubString(s, 0, 9) == "-ai prep ") then
        n = S2I(SubString(s, 9, StringLength(s)))
        if ((n == 0) or ((n >= 15) and (n <= 180))) then
            NewAI_PrepSeconds = n
            DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, J88_concat(J88_concat("[AI] Preparation override set to ", I2S(n)), " seconds, effective NEXT preparation (0=original)."))
        end
    else
        DisplayTimedTextToPlayer(p, 0.0, 0.0, 10.0, "[AI] Unknown command. Type -ai help.")
    end
    p = nil
end

function NewAI_RecordLobby()
    local pid = 0
    local humans = 0
    while true do
        if (pid >= 8) then break end
        if ((GetPlayerSlotState(Player(pid)) == PLAYER_SLOT_STATE_PLAYING) and (GetPlayerController(Player(pid)) == MAP_CONTROL_USER)) then
            humans = J88_int(humans + 1)
            if (NewAI_Host < 0) then
                NewAI_Host = pid
            end
        end
        pid = J88_int(pid + 1)
    end
    NewAI_SoloTest = (humans == 1)
end

function NewAI_Init()
    local pid = 0
    if NewAI_Ready then
        do return end
    end
    NewAI_LoadCatalog()
    Mao_AICatalog()
    US95_RegisterAI()
    Zhukov_RegisterAI()
    CT102_RegisterAI()
    UK103_RegisterAI()
    PL104_RegisterAI()
    KMT106_RegisterAI()
    NewAI_RecoveryInit()
    --  Called once for all clients, independently of per-seat economy RNG.
    NewAI_GermanRouteCursor = GetRandomInt(0, 4)
    NewAI_Counts = InitHashtable()
    NewAI_Blocked = InitHashtable()
    NewAI_SiteBlocked = InitHashtable()
    NewAI_HellPowerCache = InitHashtable()
    NewAI_ChatTrigger = CreateTrigger()
    while true do
        if (pid >= 8) then break end
        NewAI_Level[pid] = DifficultyChoice_Level
        NewAI_Rng[pid] = ModuloInteger(J88_int(NewAI_Seed + J88_int(pid * 7919)), 65536)
        if (not NewAI_Controlled[pid]) then
            NewAI_Status[pid] = "human"
        end
        TriggerRegisterPlayerChatEvent(NewAI_ChatTrigger, Player(pid), "-ai", false)
        if ((GetPlayerSlotState(Player(pid)) ~= PLAYER_SLOT_STATE_PLAYING) or (GetPlayerController(Player(pid)) ~= MAP_CONTROL_USER)) then
            NewAI_SetControl(pid)
        end
        pid = J88_int(pid + 1)
    end
    TriggerAddAction(NewAI_ChatTrigger, NewAI_OnChat)
    NewAI_Ready = true
    DifficultyChoice_Init()
    NewAI_Timer = CreateTimer()
    TimerStart(NewAI_Timer, 2.0, true, NewAI_OnTick)
    DisplayTextToForce(GetPlayersAll(), "Computer players command unoccupied armies and replace players who leave. Type -ai for AI information.")
end
